SET ROLE talus_fn;
CREATE TABLE app.deposit_hold_settlement(tenant_id uuid NOT NULL,deposit_hold_settlement_id uuid NOT NULL DEFAULT gen_random_uuid(),hold_journal_entry_id uuid NOT NULL,trip_id uuid NOT NULL,settled_at timestamptz NOT NULL DEFAULT clock_timestamp(),captured_cents bigint NOT NULL CHECK(captured_cents>=0),released_cents bigint NOT NULL CHECK(released_cents>=0),excess_receivable_cents bigint NOT NULL CHECK(excess_receivable_cents>=0),capture_journal_entry_id uuid,release_journal_entry_id uuid,receivable_journal_entry_id uuid,PRIMARY KEY(tenant_id,deposit_hold_settlement_id),UNIQUE(tenant_id,hold_journal_entry_id),UNIQUE(tenant_id,trip_id),FOREIGN KEY(tenant_id,hold_journal_entry_id) REFERENCES app.journal_entry(tenant_id,journal_entry_id),FOREIGN KEY(tenant_id,trip_id) REFERENCES app.trip(tenant_id,trip_id));
CREATE TRIGGER deposit_settlement_append BEFORE UPDATE OR DELETE ON app.deposit_hold_settlement FOR EACH ROW EXECUTE FUNCTION app.enforce_append_only();
CREATE OR REPLACE FUNCTION app.settle_deposit_hold(p_hold uuid,p_trip uuid,p_capture bigint,p_release bigint,p_excess bigint) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,pg_catalog AS $$ DECLARE t uuid:=app.current_context_tenant_id();a uuid;held bigint;id uuid:=gen_random_uuid();BEGIN PERFORM app.require_context();SELECT ledger_account_id INTO a FROM app.ledger_account WHERE tenant_id=t AND account_code='deposits_held';IF NOT FOUND THEN RAISE EXCEPTION 'NO_VALID_DEPOSIT_HOLD_POSTING' USING ERRCODE='P0002';END IF;SELECT amount_cents INTO held FROM app.ledger_posting WHERE tenant_id=t AND journal_entry_id=p_hold AND ledger_account_id=a AND direction='credit' FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'NO_VALID_DEPOSIT_HOLD_POSTING' USING ERRCODE='P0002';END IF;IF p_capture+p_release>held THEN RAISE EXCEPTION 'SETTLEMENT_EXCEEDS_HOLD_AMOUNT' USING ERRCODE='P0003';END IF;INSERT INTO app.deposit_hold_settlement(tenant_id,deposit_hold_settlement_id,hold_journal_entry_id,trip_id,captured_cents,released_cents,excess_receivable_cents) VALUES(t,id,p_hold,p_trip,p_capture,p_release,p_excess);PERFORM app.append_audit('deposit.settled','deposit_hold_settlement',id);RETURN id;EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'DEPOSIT_ALREADY_SETTLED' USING ERRCODE='23505';END;$$;
ALTER TABLE app.deposit_hold_settlement ENABLE ROW LEVEL SECURITY;ALTER TABLE app.deposit_hold_settlement FORCE ROW LEVEL SECURITY;CREATE POLICY tenant_context_policy ON app.deposit_hold_settlement USING(tenant_id=app.current_context_tenant_id() AND app.context_is_valid()) WITH CHECK(tenant_id=app.current_context_tenant_id() AND app.context_is_valid());
REVOKE ALL ON app.deposit_hold_settlement FROM PUBLIC,talus_staff,talus_api,talus_customer;
GRANT EXECUTE ON FUNCTION app.settle_deposit_hold(uuid,uuid,bigint,bigint,bigint) TO talus_staff,talus_api;
RESET ROLE;
